import re
def readable(text):
 chunks=re.split(r'(`[^`]*`)',text)
 for i,x in enumerate(chunks):
  if x.startswith('`'):continue
  x=re.sub(r'(?<=\d)(?=(?:tuples|shapes|single|candidate|fixed|mark|part|reversal|negative|significant|conditional|case|first|raw|tasks|contexts|outcomes|initial|normalised|bytes|byte|files|sources|retained|review|analysis|frequency|commands|matching|content|objectives|point|table|row|examples|curve|after|for|under|only|primitive|accuracy|while|through|and|outside|sign|no|numerical|unchanged|compared|seeds|under|from|significant|core|documents))', ' ',x)
  x=x.replace('December2020syllabus','December 2020 syllabus').replace('Grade12','Grade 12').replace('All42','All 42').replace('all27','all 27').replace('all168','all 168').replace('all28','all 28').replace('all24','all 24').replace('with independent correctS3evidence','with independent correct S3 evidence').replace('actualD2sum','actual D2 sum').replace('→D3sum','→D3 sum').replace('the4markcap','the 4-mark cap').replace('R1only','R1 only').replace('R2only','R2 only').replace('per28','per 28')
  prefixes='all|All|with|over|minority|coincidence|split|alone|exact|stale|sum|current|remains|packing|most|sample|not|stored|actual|derived|field|marked|reproduced|angle|once|includes|and|special|own|maximum|distinguish|notes|calculus|motion|log|visual|readable|endpoint|roots|the|leaving|earns|true|only|correct|canonical|item'
  x=re.sub(r'\b('+prefixes+r')(?=\d)',r'\1 ',x)
  suffixes='Apply|Analyse|change|tuplekeys|removed|added|readable|canonical|answers|also|tariff|criteria|exact|alpha|edge|independently|credit|decimal|remains'
  x=re.sub(r'(?<=\d)(?=(?:'+suffixes+r'))',' ',x)
  for old,new in [('candidatefiles','candidate files'),('markcap','mark cap'),('significantfigures','significant figures'),('leavingR1','leaving R1'),('earnsR2','earns R2'),('earnsR1','earns R1'),('underOD-1','under OD-1'),('half-up720','half-up 720'),('frequencyrows','frequency rows'),('markpenalty','mark penalty'),('markdeduction','mark deduction'),('onlywith','only with'),('onlywww','only www'),('NSSCAS2025PDF345item4','NSSCAS 2025 PDF345 item 4'),('**comparable Cambridge**9709_m16_ms_12PDF3Penalties','**comparable Cambridge** 9709_m16_ms_12.pdf PDF3 Penalties'),('33/2m','33/2 m')]:x=x.replace(old,new)
  chunks[i]=x
 return ''.join(chunks)
